INSERT INTO `ai_recommendation_logs` (`id`, `user_id`, `request_type`, `prompt_summary`, `ai_response`, `model_used`, `created_at`) VALUES ('1', '58', 'event_planning', 'Google Gemini AI for club #4', '{\n  \"analysis_summary\": \"The proposed events are tailored for the Accounting Info System Society (AISS) at Bestlink College of the Philippines, focusing strictly on accounting information literacy, enterprise resource planning (ERP), and financial technology integration in business applications. All dates avoid Philippine holidays, examination weeks, and are scheduled on optimal weekend/Friday slots.\",\n  \"organization\": \"Accounting Info System Society (AISS)\",\n  \"plans\": [\n    {\n      \"title\": \"ERP Business Process Integration Challenge\",\n      \"category\": \"Academic\",\n      \"description\": \"An interactive inter-year simulation competition where student teams configure enterprise resource planning modules to streamline simulated corporate financial workflows, inventory management, and automated reporting.\",\n      \"recommended_date\": \"2026-03-20T09:00\",\n      \"recommended_venue\": \"BCP Computer Laboratory 3 & Online Hybrid Platform\",\n      \"target_audience\": \"BSBA Financial Management and BS Accountancy Students\",\n      \"estimated_budget\": 6000,\n      \"accessibility_verdict\": \"Fully accessible via on-campus labs and remote desktop access for hybrid participants.\",\n      \"holiday_check\": \"Verified clear of any Philippine holidays or academic exam weeks.\",\n      \"clash_status\": \"Conflict-Free & Accessible\",\n      \"feasibility_score\": 96,\n      \"expected_outcomes\": \"Enhanced practical competency in ERP navigation, enterprise data mapping, and collaborative financial problem-solving.\"\n    },\n    {\n      \"title\": \"FinTech & Digital Auditing Symposium\",\n      \"category\": \"Academic\",\n      \"description\": \"A half-day professional seminar featuring industry practitioners discussing modern financial technology integration, digital ledger systems, and automated compliance auditing tools used in commercial business environments.\",\n      \"recommended_date\": \"2026-07-17T14:00\",\n      \"recommended_venue\": \"BCP Multi-Purpose Hall\",\n      \"target_audience\": \"AISS Members and Department Faculty\",\n      \"estimated_budget\": 5500,\n      \"accessibility_verdict\": \"Wheelchair accessible with sign language interpreter support and audio amplification systems.\",\n      \"holiday_check\": \"Verified clear of any Philippine holidays or academic exam weeks.\",\n      \"clash_status\": \"Conflict-Free & Accessible\",\n      \"feasibility_score\": 94,\n      \"expected_outcomes\": \"Broader awareness of current fintech trends, electronic auditing standards, and career pathways in accounting information systems.\"\n    },\n    {\n      \"title\": \"Data Analytics for Accountants Workshop\",\n      \"category\": \"Academic\",\n      \"description\": \"A hands-on technical workshop focusing on data visualization tools and business intelligence software tailored for financial data interpretation, predictive budgeting, and executive reporting.\",\n      \"recommended_date\": \"2026-09-18T09:00\",\n      \"recommended_venue\": \"BCP Computer Laboratory 1\",\n      \"target_audience\": \"Junior and Senior AISS Members\",\n      \"estimated_budget\": 5000,\n      \"accessibility_verdict\": \"Standard computer lab accessibility with ergonomic workstations available.\",\n      \"holiday_check\": \"Verified clear of any Philippine holidays or academic exam weeks.\",\n      \"clash_status\": \"Conflict-Free & Accessible\",\n      \"feasibility_score\": 95,\n      \"expected_outcomes\": \"Proficiency in transforming raw corporate data into actionable financial dashboards and data-driven insights.\"\n    }\n  ],\n  \"scheduling_insights\": \"All scheduled events are strategically positioned outside major examination periods (such as March and May midterms/finals) and national holidays, ensuring maximum student participation and institutional resource availability.\"\n}', 'Generative AI Engine', '2026-10-01 12:55:15');
INSERT INTO `ai_recommendation_logs` (`id`, `user_id`, `request_type`, `prompt_summary`, `ai_response`, `model_used`, `created_at`) VALUES ('2', '58', 'event_planning', 'Google Gemini AI for club #7', '{\n  \"analysis_summary\": \"The proposed events for the Criminal Justice Student Unit (CJSU) integrate contemporary legal and investigative themes inspired by legislative accountability proceedings (such as impeachment inquiries regarding the proper use and transparency of confidential and public funds) into practical criminology disciplines including moot court trials, criminalistics, and investigative accounting workshops. All dates avoid PH holidays, exam weeks, and conflicts.\",\n  \"organization\": \"Criminal Justice Student Unit (CJSU)\",\n  \"plans\": [\n    {\n      \"title\": \"Lex et Fiscus: Moot Court Trial and Legislative Inquiry Simulation on Public Fund Accountability\",\n      \"category\": \"Academic\",\n      \"description\": \"A specialized moot court trial and legislative inquiry simulation modeled after high-profile government accountability hearings. Criminology students will practice examining documentary evidence, questioning hostile witnesses, and applying rules of evidence regarding the alleged misuse of confidential funds.\",\n      \"recommended_date\": \"2026-03-27T13:00\",\n      \"recommended_venue\": \"BCP Moot Court Room / Audio-Visual Room\",\n      \"target_audience\": \"3rd and 4th Year Criminology Students\",\n      \"estimated_budget\": 5000,\n      \"accessibility_verdict\": \"Fully accessible on-campus venue with standard wheelchair ramps and audio-visual support.\",\n      \"holiday_check\": \"Checked against 2026 PH holidays and exam schedules. Clear.\",\n      \"clash_status\": \"Conflict-Free & Accessible\",\n      \"feasibility_score\": 96,\n      \"expected_outcomes\": \"Enhanced litigation skills, deeper understanding of constitutional checks and balances, and practical application of criminal procedure.\"\n    },\n    {\n      \"title\": \"Forensic Auditing & Paper Trail Analysis Workshop: Tracing Disputed Allocations\",\n      \"category\": \"Academic\",\n      \"description\": \"A hands-on criminalistics and investigative workshop focusing on forensic accounting, document examination, and financial paper-trail tracing. Inspired by legislative budget scrutiny, students learn how to detect anomalies, falsified liquidation reports, and paper trails in white-collar crimes.\",\n      \"recommended_date\": \"2026-04-24T13:00\",\n      \"recommended_venue\": \"BCP Computer Laboratory 3\",\n      \"target_audience\": \"All CJSU Members\",\n      \"estimated_budget\": 4500,\n      \"accessibility_verdict\": \"Located on the ground floor computer lab, fully accessible for all students.\",\n      \"holiday_check\": \"Checked against 2026 PH holidays and exam schedules. Clear.\",\n      \"clash_status\": \"Conflict-Free & Accessible\",\n      \"feasibility_score\": 94,\n      \"expected_outcomes\": \"Equipped students with specialized financial investigation skills vital for modern law enforcement and anti-corruption agencies.\"\n    },\n    {\n      \"title\": \"Chain of Custody & Evidence Integrity Seminar: Safeguarding High-Profile Exhibits\",\n      \"category\": \"Academic\",\n      \"description\": \"A tactical and investigative seminar addressing the protocols of preserving the chain of custody for sensitive documentary and digital evidence presented during congressional and judicial investigations. Features guest speakers from law enforcement agencies.\",\n      \"recommended_date\": \"2026-06-19T13:00\",\n      \"recommended_venue\": \"BCP Gymnasium and Cultural Center\",\n      \"target_audience\": \"BS Criminology Students\",\n      \"estimated_budget\": 5500,\n      \"accessibility_verdict\": \"Spacious venue with proper ventilation, seating, and PWD-friendly access points.\",\n      \"holiday_check\": \"Checked against 2026 PH holidays and exam schedules. Clear.\",\n      \"clash_status\": \"Conflict-Free & Accessible\",\n      \"feasibility_score\": 95,\n      \"expected_outcomes\": \"Heightened awareness of evidence handling integrity and adherence to legal standards to prevent evidence tampering or dismissal in court.\"\n    }\n  ],\n  \"scheduling_insights\": \"Friday afternoons were strategically chosen to maximize student participation without interfering with regular weekday academic cycles or weekend rest periods, ensuring zero overlap with the 2026 Philippine holiday calendar and examination weeks.\"\n}', 'Generative AI Engine', '2026-10-01 14:43:05');
